<template>
  <section class="login h-full w-full flex flex-col">
    <div class="flex justify-end">
      <NuxtLink :to="{ name: 'login' }">
        <Button variant="secondary" size="sm">Log In</Button>
      </NuxtLink>
    </div>
    <div class="self-center flex flex-col gap-6 p-6 flex-auto w-full justify-center max-w-[552px] max-lg:px-0">
      <SignUpStepper v-model="stepIndex" />
      <div class="flex flex-col gap-3">
        <h1 class="font-semibold text-2xl leading-6">Create your account</h1>
        <p class="text-sm text-description">Join our community of canvassers</p>
      </div>
      <form class="grid grid-cols-2 gap-4" @submit="onSubmit">
        <FormItemWrapper name="first_name" label="First Name" item-class="col-span-2 sm:col-span-1">
          <template #default="{ slots }">
            <Input
              id="first_name"
              type="text"
              placeholder="John"
              v-bind="slots.componentField"
              :disabled="isSigningUp"
            />
          </template>
        </FormItemWrapper>
        <FormItemWrapper name="last_name" label="Last Name" item-class="col-span-2 sm:col-span-1">
          <template #default="{ slots }">
            <Input id="last_name" type="text" placeholder="Doe" v-bind="slots.componentField" :disabled="isSigningUp" />
          </template>
        </FormItemWrapper>
        <FormItemWrapper name="email" label="Email" item-class="col-span-2 sm:col-span-1">
          <template #default="{ slots }">
            <Input
              id="email"
              type="text"
              placeholder="name@example.com"
              v-bind="slots.componentField"
              :disabled="isSigningUp"
            />
          </template>
        </FormItemWrapper>
        <FormItemWrapper name="phone" label="Phone Number" item-class="col-span-2 sm:col-span-1">
          <template #default="{ slots }">
            <Input
              id="phone"
              v-maska
              type="text"
              placeholder="+1 555-555-5555"
              data-maska="+# ###-###-####"
              v-bind="slots.componentField"
              :disabled="isSigningUp"
            />
          </template>
        </FormItemWrapper>
        <FormItemWrapper name="password" label="Password" item-class="col-span-2">
          <template #default="{ slots }">
            <KitFormPasswordInput
              id="password"
              placeholder="Enter your password"
              :component-field="slots.componentField"
              :disabled="isSigningUp"
              autocomplete="new-password"
            />
          </template>
        </FormItemWrapper>
        <FormItemWrapper name="confirm_password" label="Confirm Password" item-class="col-span-2">
          <template #default="{ slots }">
            <KitFormPasswordInput
              id="confirm_password"
              placeholder="Confirm your password"
              :component-field="slots.componentField"
              :disabled="isSigningUp"
              autocomplete="new-password"
            />
          </template>
        </FormItemWrapper>
        <FormItemWrapper
          name="sms_consent"
          type="checkbox"
          :unchecked-value="false"
          :checked-value="true"
          item-class="col-span-2"
        >
          <template #default="{ slots }">
            <div class="flex flex-row items-start gap-2">
              <Checkbox
                id="sms_consent"
                data-testid="signup-sms-consent"
                :model-value="slots.value"
                v-bind="slots.componentField"
                :disabled="isSigningUp"
                class="mt-0.5"
              />
              <div class="flex flex-col gap-0.5">
                <Label for="sms_consent" class="text-sm font-normal">
                  Text me about work opportunities from Patriot Grassroots
                </Label>
                <p class="text-xs text-description">
                  Automated texts; consent is not a condition of registration. Message frequency varies, message &amp;
                  data rates may apply. Reply STOP to opt out or HELP for help.
                </p>
              </div>
            </div>
          </template>
        </FormItemWrapper>
        <FormItemWrapper
          name="agreed_to_terms"
          type="checkbox"
          :unchecked-value="false"
          :checked-value="true"
          item-class="col-span-2"
        >
          <template #default="{ slots }">
            <div class="flex flex-row items-center gap-2">
              <Checkbox
                id="agreed_to_terms"
                :model-value="slots.value"
                v-bind="slots.componentField"
                :disabled="isSigningUp"
              />
              <Label for="agreed_to_terms" class="text-sm font-normal">
                I agree to the
                <NuxtLink :to="{ name: 'privacy' }" target="_blank" class="underline">Terms &amp; Conditions</NuxtLink>
              </Label>
            </div>
          </template>
        </FormItemWrapper>
        <Button
          variant="default"
          class="w-full h-10 col-span-2"
          :loading="isSigningUp"
          :disabled="isSigningUp"
          type="submit"
          >Next</Button
        >
      </form>
    </div>
  </section>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import { toTypedSchema } from '@vee-validate/zod';
import { useSignUp } from '~/mutations/signUp';
import { signUpFormSchema } from '~/constants/validationSchemas/signUp';
import { computed } from 'vue';
import { useRoute } from 'vue-router';

const route = useRoute('sign-up');
const referralCode = computed(() => (route.query.referral_code ? String(route.query.referral_code) : undefined));

useSeoMeta({
  title: 'Sign Up',
  description: 'Sign Up and join our community of canvassers.',
});

definePageMeta({
  layout: 'login',
  auth: {
    unauthenticatedOnly: true,
    navigateAuthenticatedTo: '/projects',
  },
});

const stepIndex = ref<number>(1);

const { signUp, isSigningUp } = useSignUp();

const formSchema = toTypedSchema(signUpFormSchema);

const { handleSubmit } = useForm({
  validationSchema: formSchema,
});

const onSubmit = handleSubmit(({ confirm_password: _ignore, ...signUpForm }) => {
  signUp({
    ...signUpForm,
    // handleSubmit only fires once the schema validated agreed_to_terms === true.
    agreed_to_terms: true,
    referral_code: referralCode.value,
    time_zone: Intl.DateTimeFormat().resolvedOptions().timeZone,
  });
});
</script>

<style scoped lang="scss"></style>
